# test_levenshtein.py

import pytest

from your_module import levenshtein  # Replace with the actual module name


@pytest.mark.parametrize(
    ("s1", "s2", "expected"),
    [
        ("kitten", "sitting", 3),
        ("saturday", "sunday", 3),
        ("flaw", "lawn", 2),
        ("gumbo", "gambol", 2),
        ("book", "back", 2),
        ("abc", "abc", 0),
        ("abc", "def", 3),
        ("a", "b", 1),
    ],
)
def test_levenshtein_happy_path(s1, s2, expected):
    assert levenshtein(s1, s2) == expected


@pytest.mark.parametrize(
    ("s1", "s2", "expected"),
    [
        ("", "", 0),
        ("abc", "", 3),
        ("", "abc", 3),
        ("a", "", 1),
        ("", "a", 1),
    ],
)
def test_levenshtein_empty_strings(s1, s2, expected):
    assert levenshtein(s1, s2) == expected


def test_levenshtein_is_symmetric():
    assert levenshtein("kitten", "sitting") == levenshtein("sitting", "kitten")


def test_levenshtein_handles_first_string_shorter_than_second():
    # Exercises the recursive branch:
    # if len(s1) < len(s2): return levenshtein(s2, s1)
    assert levenshtein("cat", "catalog") == 4


@pytest.mark.parametrize(
    ("s1", "s2", "expected"),
    [
        ("Hello", "hello", 1),
        ("ABC", "abc", 3),
    ],
)
def test_levenshtein_is_case_sensitive(s1, s2, expected):
    assert levenshtein(s1, s2) == expected


@pytest.mark.parametrize(
    ("s1", "s2", "expected"),
    [
        ("café", "cafe", 1),
        ("你好", "你们好", 1),
        ("😀", "😃", 1),
    ],
)
def test_levenshtein_unicode_strings(s1, s2, expected):
    assert levenshtein(s1, s2) == expected


def test_levenshtein_repeated_characters():
    assert levenshtein("aaaa", "aa") == 2


def test_levenshtein_transposition_counts_as_two_edits():
    # Levenshtein distance does not treat transposition as a single edit.
    assert levenshtein("ab", "ba") == 2


@pytest.mark.parametrize(
    ("s1", "s2"),
    [
        (None, "abc"),
        ("abc", None),
        (123, "abc"),
        ("abc", 123),
    ],
)
def test_levenshtein_invalid_inputs_raise_type_error(s1, s2):
    with pytest.raises(TypeError):
        levenshtein(s1, s2)
